import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CqdVOxXJ.js";const n="/rakkii-cars-guide/screenshots/v2/a02-dashboard.png",k=JSON.parse('{"title":"Your day at the desk","description":"","frontmatter":{},"headers":[],"relativePath":"desk/index.md","filePath":"desk/index.md","lastUpdated":1794643263000}'),s={name:"desk/index.md"};function d(i,e,h,l,c,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="your-day-at-the-desk" tabindex="-1">Your day at the desk <a class="header-anchor" href="#your-day-at-the-desk" aria-label="Permalink to &quot;Your day at the desk&quot;">​</a></h1><p><strong>For:</strong> Owner (and admin) · <strong>You use:</strong> every hub</p><p>The desk runs each job from booking to release, and keeps the money, people and settings in order. This page is your daily routine. The <a href="/rakkii-cars-guide/desk/job/01-open-a-job">8 job steps</a> cover one car from start to finish.</p><h2 id="morning-see-what-needs-you" tabindex="-1">Morning: see what needs you <a class="header-anchor" href="#morning-see-what-needs-you" aria-label="Permalink to &quot;Morning: see what needs you&quot;">​</a></h2><ol><li><strong>Workshop › Dashboard</strong> (your home page). Read the announcements, then <strong>Priority jobs</strong> and the five numbers: <strong>Cars in shop</strong>, <strong>Ready for pickup</strong>, <strong>On hold</strong>, <strong>Cash in today</strong> and <strong>Overdue invoices</strong>.</li><li><strong>Workshop › Shop board</strong>. Every car in play, by status. Press <strong>What&#39;s left</strong> on a card to see what&#39;s still open without leaving the board.</li><li><strong>Workshop › Customer activity</strong>. Customers who approved or declined an estimate, or sent a payment proof, since you last looked. The bell in the top bar shows the count.</li></ol><p><img src="'+n+'" alt="Dashboard"></p><h2 id="during-the-day-move-each-car-along" tabindex="-1">During the day: move each car along <a class="header-anchor" href="#during-the-day-move-each-car-along" aria-label="Permalink to &quot;During the day: move each car along&quot;">​</a></h2><p>Open a job and press its blue <strong>next-step button</strong>. It always names the next thing to do and takes you there. The full path:</p><table tabindex="0"><thead><tr><th>Step</th><th>You do</th><th>Status after</th></tr></thead><tbody><tr><td><a href="/rakkii-cars-guide/desk/job/01-open-a-job">1. Open a job</a></td><td><strong>New job</strong>: customer, car, work</td><td><strong>Booked</strong></td></tr><tr><td><a href="/rakkii-cars-guide/desk/job/02-work-and-quote">2. Add work and save the quote</a></td><td>Work lines, then <strong>Save quote</strong></td><td><strong>Quoted</strong></td></tr><tr><td><a href="/rakkii-cars-guide/desk/job/03-customer-approval">3. Get the customer&#39;s OK</a></td><td>Send the estimate link; take the deposit if needed</td><td><strong>Quoted</strong></td></tr><tr><td><a href="/rakkii-cars-guide/desk/job/04-start-work">4. Assign and start work</a></td><td>Pick the technician, <strong>Approve and start work</strong></td><td><strong>Under repair</strong></td></tr><tr><td><a href="/rakkii-cars-guide/desk/job/05-qc-and-ready">5. QC and ready for pickup</a></td><td>Technician sends to QC and takes 4 photos; you mark ready</td><td><strong>Ready for pickup</strong></td></tr><tr><td><a href="/rakkii-cars-guide/desk/job/06-bill-and-collect">6. Bill and collect</a></td><td><strong>Bill customer</strong>, <strong>Record payment</strong></td><td>(no change)</td></tr><tr><td><a href="/rakkii-cars-guide/desk/job/07-release">7. Release the car</a></td><td>&quot;Can the car leave?&quot;, tick the checks, <strong>Release car</strong></td><td><strong>Released</strong></td></tr><tr><td><a href="/rakkii-cars-guide/desk/job/08-mark-done">8. Mark the job done</a></td><td>Check nothing is left, <strong>Mark as done</strong></td><td><strong>Done</strong></td></tr></tbody></table><p>Insurance and corporate jobs add a step or two: see <a href="/rakkii-cars-guide/desk/insurance-jobs">Insurance jobs</a> and <a href="/rakkii-cars-guide/desk/corporate-jobs">Corporate &amp; government jobs</a>.</p><h2 id="through-the-day-money-that-arrives" tabindex="-1">Through the day: money that arrives <a class="header-anchor" href="#through-the-day-money-that-arrives" aria-label="Permalink to &quot;Through the day: money that arrives&quot;">​</a></h2><ul><li><strong>Payment proofs</strong>: customers can upload a GCash or Maya screenshot from their pay link. The job shows &quot;The customer uploaded a payment proof that needs checking.&quot; Press <strong>Review payment proof</strong>, or open <strong>Finance › Payments</strong>. Check the money arrived before you confirm it.</li><li><strong>Cash today</strong>: <strong>Finance › Cash</strong> shows the money in and out for the day.</li></ul><h2 id="end-of-day" tabindex="-1">End of day <a class="header-anchor" href="#end-of-day" aria-label="Permalink to &quot;End of day&quot;">​</a></h2><ul><li>[ ] No car on the board without a next step (holds have a reason)</li><li>[ ] Every payment received today is recorded</li><li>[ ] Payment proofs reviewed</li><li>[ ] Clock kiosk and attendance checked (<strong>HR › Attendance</strong>)</li></ul><h2 id="weekly-and-monthly" tabindex="-1">Weekly and monthly <a class="header-anchor" href="#weekly-and-monthly" aria-label="Permalink to &quot;Weekly and monthly&quot;">​</a></h2><p>These are in <a href="/rakkii-cars-guide/desk/running-the-shop">Running the shop</a>: payroll, payables, parts stock, reports, month close and settings.</p>',16)])])}const p=t(s,[["render",d]]);export{k as __pageData,p as default};
